import { readFileSync } from 'node:fs';
import { describe,expect,it } from 'vitest';
import { Manifest,Withdrawal,validatePackage,validatePackageMetadata,verifySigned } from '../src/lib/inspiration/protocol';
import { assertEnvelopeScope,assertPublicationScope } from '../src/lib/inspiration/publication-scope';

// Generated by the real A Python publisher using only a synthetic local image.
// Contains a test public key, never the signing private key or account credentials.
const fixture=JSON.parse(readFileSync(new URL('./fixtures/inspiration-library-python.json',import.meta.url),'utf8'));
const keys={[fixture.keyId]:fixture.publicKey};
const raw=Buffer.from(JSON.stringify(fixture.manifest));
const files=new Map<string,Buffer>(Object.entries(fixture.files as Record<string,string>).map(([path,data])=>[path,Buffer.from(data,'base64')]));
const library={id:fixture.recipient.library_id,kind:'SHARED' as const,ownerId:'synthetic-owner',legacyWorkspaceId:null};

describe('Python A to TypeScript B shared-library protocol',()=>{
  it('authenticates actual Python signatures, records, images and exact library recipient',async()=>{
    expect(fixture.synthetic_only).toBe(true);
    const metadata=validatePackageMetadata(raw,files.get('records.jsonl')!,keys);
    assertEnvelopeScope(metadata.manifest,library,fixture.recipient.origin);
    for(const record of metadata.records)if(record.case)assertPublicationScope(record.case,library,fixture.recipient.origin);
    const result=await validatePackage(raw,files,keys);expect(result.records.length).toBeGreaterThan(0);expect(result.mimes.size).toBe(1);
    const withdrawal=verifySigned(Withdrawal.parse(fixture.withdrawal),keys);assertEnvelopeScope(withdrawal,library,fixture.recipient.origin);
  });
  it('never treats a v2 library package or withdrawal as a v1 private workspace',()=>{
    expect(()=>assertEnvelopeScope(fixture.manifest,library.id,fixture.recipient.origin)).toThrow('recipient');
    expect(()=>assertEnvelopeScope(fixture.withdrawal,library.id,fixture.recipient.origin)).toThrow('recipient');
    const {records}=validatePackageMetadata(raw,files.get('records.jsonl')!,keys);
    expect(()=>assertPublicationScope(records[0]!.case!,library.id,fixture.recipient.origin)).toThrow('recipient');
  });
  it('rejects wrong library/origin and legacy envelopes in the shared namespace, including empty withdrawals',()=>{
    expect(()=>assertEnvelopeScope(fixture.manifest,{...library,id:'other-library'},fixture.recipient.origin)).toThrow('recipient');
    expect(()=>assertEnvelopeScope(fixture.withdrawal,library,'https://other.example.invalid')).toThrow('recipient');
    expect(()=>assertEnvelopeScope({schema_version:1},library,fixture.recipient.origin)).toThrow('recipient');
    expect(()=>assertEnvelopeScope({schema_version:2,recipient:{...fixture.recipient,library_id:'other-library'}},library,fixture.recipient.origin)).toThrow('recipient');
  });
  it('requires the signed recipient on v2 and forbids extra recipient fields on v1',()=>{
    const {recipient:_,...without}=fixture.manifest;
    expect(Manifest.safeParse(without).success).toBe(false);
    expect(Manifest.safeParse({...fixture.manifest,schema_version:1}).success).toBe(false);
    expect(Withdrawal.safeParse({...fixture.withdrawal,recipient:{...fixture.recipient,workspace_id:'wildcard'}}).success).toBe(false);
  });
});
